"""Decode Ways — count paths where each step consumes one or two digits.

A single digit works unless it is '0'; a pair works when it lands in 10..26.

Time: O(n)   Space: O(1)
"""


class Solution:
    def numDecodings(self, s: str) -> int:
        if not s or s[0] == "0":
            return 0
        two_back, one_back = 1, 1
        for i in range(1, len(s)):
            current = 0
            if s[i] != "0":
                current += one_back
            if 10 <= int(s[i - 1:i + 1]) <= 26:
                current += two_back
            if current == 0:
                return 0
            two_back, one_back = one_back, current
        return one_back
